import React, { useState } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Modal, FlatList, Pressable } from 'react-native';
import { ChevronDown, Plus, User, Check } from 'lucide-react-native';
import { COLORS, BORDER_RADIUS, SPACING } from '../styles/theme';
import { useApp } from '../context/AppContext';

interface ProfileSwitcherProps {
  onAddProfilePress: () => void;
}

export const ProfileSwitcher: React.FC<ProfileSwitcherProps> = ({ onAddProfilePress }) => {
  const { profiles, currentProfile, switchProfile } = useApp();
  const [modalVisible, setModalVisible] = useState(false);

  if (!currentProfile) return null;

  const handleSelectProfile = async (id: string) => {
    await switchProfile(id);
    setModalVisible(false);
  };

  // Get initials for profile avatar
  const getInitials = (name: string) => {
    return name.trim().charAt(0).toUpperCase();
  };

  // Calculate age from date of birth string (YYYY-MM-DD)
  const calculateAge = (dobString: string) => {
    try {
      const birthDate = new Date(dobString);
      const today = new Date();
      let age = today.getFullYear() - birthDate.getFullYear();
      const m = today.getMonth() - birthDate.getMonth();
      if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
        age--;
      }
      return `${age} yrs`;
    } catch (e) {
      return '';
    }
  };

  return (
    <View>
      <TouchableOpacity
        style={styles.container}
        onPress={() => setModalVisible(true)}
        activeOpacity={0.7}
      >
        <View style={styles.avatar}>
          <Text style={styles.avatarText}>{getInitials(currentProfile.name)}</Text>
        </View>
        <View style={styles.info}>
          <Text style={styles.name}>{currentProfile.name}</Text>
          <Text style={styles.relation}>
            {currentProfile.relationship} • {calculateAge(currentProfile.dob)}
          </Text>
        </View>
        <ChevronDown size={18} color={COLORS.textMuted} style={styles.chevron} />
      </TouchableOpacity>

      <Modal
        visible={modalVisible}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setModalVisible(false)}
      >
        <Pressable 
          style={styles.modalOverlay} 
          onPress={() => setModalVisible(false)}
        >
          <View style={styles.modalContent}>
            <Text style={styles.modalTitle}>Switch Profile</Text>

            <FlatList
              data={profiles}
              keyExtractor={(item) => item.id}
              renderItem={({ item }) => {
                const isSelected = item.id === currentProfile.id;
                return (
                  <TouchableOpacity
                    style={[
                      styles.profileItem,
                      isSelected && styles.profileItemActive
                    ]}
                    onPress={() => handleSelectProfile(item.id)}
                  >
                    <View style={[
                      styles.avatarSmall,
                      isSelected ? styles.avatarSmallActive : null
                    ]}>
                      <Text style={styles.avatarSmallText}>{getInitials(item.name)}</Text>
                    </View>
                    <View style={styles.profileItemInfo}>
                      <Text style={styles.profileItemName}>{item.name}</Text>
                      <Text style={styles.profileItemRelation}>
                        {item.relationship} • {calculateAge(item.dob)}
                      </Text>
                    </View>
                    {isSelected && (
                      <Check size={18} color={COLORS.primaryLight} style={styles.checkIcon} />
                    )}
                  </TouchableOpacity>
                );
              }}
              style={styles.list}
            />

            <TouchableOpacity
              style={styles.addButton}
              onPress={() => {
                setModalVisible(false);
                onAddProfilePress();
              }}
            >
              <Plus size={18} color={COLORS.primaryLight} />
              <Text style={styles.addButtonText}>Add New Profile</Text>
            </TouchableOpacity>
          </View>
        </Pressable>
      </Modal>
    </View>
  );
};

