import React from 'react';
import { View, Text, StyleSheet, Dimensions, Platform } from 'react-native';
import Svg, { Path, Circle, Defs, LinearGradient, Stop, Rect, Line, Text as SvgText } from 'react-native-svg';
import { COLORS, BORDER_RADIUS, SPACING } from '../styles/theme';
import { Vital } from '../db/db';

interface TrendChartProps {
  vitals: Vital[];
  vitalName: string;
}

export const TrendChart: React.FC<TrendChartProps> = ({ vitals, vitalName }) => {
  if (vitals.length === 0) {
    return (
      <View style={[styles.card, styles.emptyContainer]}>
        <Text style={styles.emptyText}>No data points to display trend</Text>
      </View>
    );
  }

  // Get screen width for responsiveness
  const screenWidth = Dimensions.get('window').width;
  const chartWidth = Platform.OS === 'web' ? 480 : screenWidth - SPACING.lg * 2 - SPACING.md * 2;
  const chartHeight = 180;
  const paddingX = 35;
  const paddingY = 25;

  // Extract values and dates
  const values = vitals.map(v => v.value);
  const dates = vitals.map(v => {
    // Format YYYY-MM-DD to "MMM DD"
    try {
      const parts = v.test_date.split('-');
      if (parts.length === 3) {
        const dateObj = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
        return dateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      }
    } catch (e) {}
    return v.test_date;
  });

  const maxVal = Math.max(...values);
  const minVal = Math.min(...values);
  const valRange = maxVal - minVal;

  // Pad the range slightly so the line doesn't hit the absolute edges
  const yMax = maxVal + (valRange * 0.15 || 5);
  const yMin = Math.max(0, minVal - (valRange * 0.15 || 5));
  const yRange = yMax - yMin;

  // Generate coordinates
  const points = vitals.map((vital, i) => {
    const x = paddingX + (i * (chartWidth - paddingX * 2)) / Math.max(1, vitals.length - 1);
    const y = chartHeight - paddingY - ((vital.value - yMin) * (chartHeight - paddingY * 2)) / Math.max(1, yRange);
    return { x, y, value: vital.value, date: dates[i], status: vital.status };
  });

  // Build path command
  let linePath = '';
  let areaPath = '';

  if (points.length > 0) {
    linePath = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      linePath += ` L ${points[i].x} ${points[i].y}`;
    }

    // Closed path for the filled area under the line
    areaPath = `${linePath} L ${points[points.length - 1].x} ${chartHeight - paddingY} L ${points[0].x} ${chartHeight - paddingY} Z`;
  }

  // Determine status color indicator based on latest reading
  const latestVital = vitals[vitals.length - 1];
  let statusColor = COLORS.primary;
  if (latestVital.status === 'High') statusColor = COLORS.danger;
  if (latestVital.status === 'Low') statusColor = COLORS.warning;
  if (latestVital.status === 'Normal') statusColor = COLORS.success;

  return (
    <View style={styles.card}>
      <View style={styles.header}>
        <View>
          <Text style={styles.title}>{vitalName} Trends</Text>
          <Text style={styles.subtitle}>
            Latest: {latestVital.value} {latestVital.unit} 
            <Text style={{ color: statusColor, fontWeight: 'bold' }}> ({latestVital.status})</Text>
          </Text>
        </View>
        <View style={[styles.unitBadge, { backgroundColor: COLORS.cardBorder }]}>
          <Text style={styles.unitText}>{latestVital.unit}</Text>
        </View>
      </View>

      <View style={styles.chartContainer}>
        {/* Draw Custom Chart Grid using SVG */}
        <Svg width={chartWidth} height={chartHeight}>
          <Defs>
            <LinearGradient id="chartGlow" x1="0" y1="0" x2="0" y2="1">
              <Stop offset="0%" stopColor={COLORS.primary} stopOpacity="0.4" />
              <Stop offset="100%" stopColor={COLORS.primary} stopOpacity="0.0" />
            </LinearGradient>
          </Defs>

          {/* Grid lines */}
          <Line x1={paddingX} y1={paddingY} x2={chartWidth - paddingX} y2={paddingY} stroke={COLORS.cardBorder} strokeWidth="1" strokeDasharray="3,3" />
          <Line x1={paddingX} y1={(chartHeight - paddingY * 2) / 2 + paddingY} x2={chartWidth - paddingX} y2={(chartHeight - paddingY * 2) / 2 + paddingY} stroke={COLORS.cardBorder} strokeWidth="1" strokeDasharray="3,3" />
          <Line x1={paddingX} y1={chartHeight - paddingY} x2={chartWidth - paddingX} y2={chartHeight - paddingY} stroke={COLORS.cardBorder} strokeWidth="1" />

          {/* Grid Labels (Min / Max values) */}
          <SvgText x={6} y={paddingY + 3} fill={COLORS.textMuted} fontSize={10} textAnchor="start">{yMax.toFixed(0)}</SvgText>
          <SvgText x={6} y={(chartHeight - paddingY * 2) / 2 + paddingY + 3} fill={COLORS.textMuted} fontSize={10} textAnchor="start">{((yMax + yMin) / 2).toFixed(0)}</SvgText>
          <SvgText x={6} y={chartHeight - paddingY + 3} fill={COLORS.textMuted} fontSize={10} textAnchor="start">{yMin.toFixed(0)}</SvgText>

          {/* Area under the path */}
          {vitals.length > 1 && (
            <Path d={areaPath} fill="url(#chartGlow)" />
          )}

          {/* Line Path */}
          {vitals.length > 1 && (
            <Path d={linePath} fill="none" stroke={COLORS.primaryLight} strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" />
          )}

          {/* Data Points */}
          {points.map((pt, i) => {
            let ptColor = COLORS.primaryLight;
            if (pt.status === 'High') ptColor = COLORS.danger;
            if (pt.status === 'Low') ptColor = COLORS.warning;

            return (
              <Circle
                key={i}
                cx={pt.x}
                cy={pt.y}
                r={vitals.length === 1 ? "6" : "4.5"}
                fill={COLORS.cardBg}
                stroke={ptColor}
                strokeWidth="2.5"
              />
            );
          })}
        </Svg>
      </View>

      {/* X Axis Labels */}
      <View style={[styles.xAxis, { width: chartWidth }]}>
        {points.map((pt, i) => (
          <Text key={i} style={[styles.dateLabel, { left: pt.x - 20 }]}>
            {pt.date}
          </Text>
        ))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  card: {
    backgroundColor: COLORS.cardBg,
    borderColor: COLORS.cardBorder,
    borderWidth: 1,
    borderRadius: BORDER_RADIUS.lg,
    padding: SPACING.md,
    marginBottom: SPACING.md,
    overflow: 'hidden',
  },
  emptyContainer: {
    height: 120,
    justifyContent: 'center',
    alignItems: 'center',
  },
  emptyText: {
    color: COLORS.textMuted,
    fontSize: 14,
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: SPACING.md,
  },
  title: {
    fontSize: 16,
    fontWeight: 'bold',
    color: COLORS.textLight,
  },
  subtitle: {
    fontSize: 12,
    color: COLORS.textMuted,
    marginTop: 2,
  },
  unitBadge: {
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: BORDER_RADIUS.sm,
  },
  unitText: {
    color: COLORS.textMuted,
    fontSize: 11,
    fontWeight: 'bold',
  },
  chartContainer: {
    alignItems: 'center',
    justifyContent: 'center',
    marginVertical: SPACING.xs,
  },
  gridLabel: {
    color: COLORS.textMuted,
    fontSize: 10,
    width: 25,
    textAlign: 'right',
  },
  xAxis: {
    height: 20,
    marginTop: SPACING.sm,
    position: 'relative',
  },
  dateLabel: {
    position: 'absolute',
    color: COLORS.textMuted,
    fontSize: 9,
    width: 40,
    textAlign: 'center',
  },
});

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Platform } from 'react-native';
import { db, Profile, RecordDocument, Vital } from '../db/db';
import { secureStore } from '../services/secureStore';
import { mockService } from '../services/mockService';
import { aiService } from '../services/aiService';

interface AppContextType {
  profiles: Profile[];
  currentProfile: Profile | null;
  documents: RecordDocument[];
  vitals: Vital[];
  isDbReady: boolean;

  // Security / Auth State
  pinLocked: boolean;
  hasPinSet: boolean;
  unlockApp: (pin: string) => Promise<boolean>;
  setupPin: (pin: string) => Promise<void>;
  clearPin: () => Promise<void>;

  // Settings
  apiKey: string;
  saveApiKey: (key: string) => Promise<void>;
  aiMode: 'simulation' | 'gemini';
  setAiMode: (mode: 'simulation' | 'gemini') => Promise<void>;

  // Google Auth Session State
  userAccount: { name: string; email: string; photoUrl?: string } | null;
  googleClientId: string;
  signInWithGoogle: (email?: string, name?: string) => Promise<void>;
  signOutGoogle: () => Promise<void>;
  saveGoogleClientId: (id: string) => Promise<void>;

  // Operations
  loadProfiles: () => Promise<void>;
  addProfile: (name: string, dob: string, gender: string, relationship: string) => Promise<Profile>;
  deleteProfile: (id: string) => Promise<void>;
  switchProfile: (id: string) => Promise<void>;
  addDocument: (filePath: string, fileName: string, mimeType: string, testName: string, testDate: string, vitalsList: Omit<Vital, 'id' | 'document_id' | 'profile_id' | 'test_date'>[]) => Promise<void>;
  removeDocument: (docId: string) => Promise<void>;
  seedDemoData: () => Promise<void>;
  refreshProfileData: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [currentProfile, setCurrentProfile] = useState<Profile | null>(null);
  const [documents, setDocuments] = useState<RecordDocument[]>([]);
  const [vitals, setVitals] = useState<Vital[]>([]);
  const [isDbReady, setIsDbReady] = useState(false);

  // Security
  const [pinLocked, setPinLocked] = useState(true);
  const [hasPinSet, setHasPinSet] = useState(false);

  // Settings
  const [apiKey, setApiKey] = useState(process.env.EXPO_PUBLIC_GEMINI_API_KEY || '');
  const [aiMode, setAiModeState] = useState<'simulation' | 'gemini'>('simulation');

  // Google Auth States
  const [userAccount, setUserAccount] = useState<{ name: string; email: string; photoUrl?: string } | null>(null);
  const [googleClientId, setGoogleClientId] = useState('');

  // 1. Initialise database and load credentials
  useEffect(() => {
    const initApp = async () => {
      try {
        await db.initialize();

        // Load API Key from environment or secureStore fallback
        const envKey = process.env.EXPO_PUBLIC_GEMINI_API_KEY;
        if (envKey) {
          setApiKey(envKey);
        } else {
          const storedKey = await secureStore.getItem('gemini_api_key');
          if (storedKey) {
            setApiKey(storedKey);
          }
        }

        // Load Google SSO Configuration & Session
        const envGoogleId = process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID;
        let activeGoogleId = '';
        if (envGoogleId) {
          setGoogleClientId(envGoogleId);
          activeGoogleId = envGoogleId;
        } else {
          const storedGoogleId = await secureStore.getItem('google_client_id');
          if (storedGoogleId) {
            setGoogleClientId(storedGoogleId);
            activeGoogleId = storedGoogleId;
          }
        }

        // Check for Google OAuth redirect token on Web
        let hasOauthUser = false;
        if (Platform.OS === 'web' && window.location.hash) {
          const params = new URLSearchParams(window.location.hash.substring(1));
          const accessToken = params.get('access_token');
          if (accessToken) {
            try {
              const res = await fetch(`https://www.googleapis.com/oauth2/v3/userinfo?access_token=${accessToken}`);
              if (res.ok) {
                const user = await res.json();
                const account = {
                  name: user.name || 'Google User',
                  email: user.email,
                  photoUrl: user.picture || undefined,
                };
                setUserAccount(account);
                await secureStore.setItem('google_user_session', JSON.stringify(account));
                hasOauthUser = true;

                // Clear the hash fragment from the URL bar cleanly
                window.history.replaceState({}, document.title, window.location.pathname);
              }
            } catch (err) {
              console.error('Failed to fetch Google userinfo from OAuth token:', err);
            }
          }
        }

        if (!hasOauthUser) {
          const storedUser = await secureStore.getItem('google_user_session');
          if (storedUser) {
            setUserAccount(JSON.parse(storedUser));
          }
        }

        // Configure Google Signin if running natively and googleClientId exists
        if (Platform.OS !== 'web' && activeGoogleId) {
          try {
            const { GoogleSignin } = require('@react-native-google-signin/google-signin');
            GoogleSignin.configure({
              webClientId: activeGoogleId,
              offlineAccess: false,
            });
          } catch (err) {
            console.error('Failed to configure Google Sign-In on init:', err);
          }
        }

        // Load AI Mode setting
        const storedAiMode = await secureStore.getItem('ai_mode');
        if (storedAiMode) {
          setAiModeState(storedAiMode as any);
        } else {
          const initialMode = (envKey || (await secureStore.getItem('gemini_api_key'))) ? 'gemini' : 'simulation';
          setAiModeState(initialMode);
          await secureStore.setItem('ai_mode', initialMode);
        }



        // Check for security PIN
        const savedPin = await secureStore.getItem('security_pin');
        if (savedPin) {
          setHasPinSet(true);
          setPinLocked(true);
        } else {
          setHasPinSet(false);
          setPinLocked(false); // No lock if PIN is not set
        }

        await loadProfiles();
        setIsDbReady(true);
      } catch (e) {
        console.error('Failed to initialize app context:', e);
      }
    };
    initApp();
  }, []);

  // Load profiles and set default active
  const loadProfiles = async () => {
    const list = await db.getProfiles();
    setProfiles(list);

    // Set active profile to the first one if not set
    if (list.length > 0) {
      const activeId = await secureStore.getItem('active_profile_id');
      const active = list.find(p => p.id === activeId) || list[0];
      setCurrentProfile(active);
      await loadProfileData(active.id);
    } else {
      setCurrentProfile(null);
      setDocuments([]);
      setVitals([]);
    }
  };

  // Load documents and vitals for a specific profile
  const loadProfileData = async (profileId: string) => {
    const docs = await db.getDocuments(profileId);
    const vList = await db.getVitals(profileId);
    setDocuments(docs);
    setVitals(vList);
  };

  const refreshProfileData = async () => {
    if (currentProfile) {
      await loadProfileData(currentProfile.id);
    }
  };

  // Profile operations
  const addProfile = async (name: string, dob: string, gender: string, relationship: string) => {
    const newProfile: Profile = {
      id: `profile_${mockService.uuid()}`,
      name,
      dob,
      gender,
      relationship
    };
    await db.createProfile(newProfile);
    await loadProfiles();

    // Auto-select newly created profile
    await switchProfile(newProfile.id);
    return newProfile;
  };

  const deleteProfile = async (id: string) => {
    await db.deleteProfile(id);
    const savedActiveId = await secureStore.getItem('active_profile_id');
    if (savedActiveId === id) {
      await secureStore.removeItem('active_profile_id');
    }
    await loadProfiles();
  };

  const switchProfile = async (id: string) => {
    const active = profiles.find(p => p.id === id);
    if (active) {
      setCurrentProfile(active);
      await secureStore.setItem('active_profile_id', id);
      await loadProfileData(id);
    }
  };

  // Security Operations
  const unlockApp = async (pin: string): Promise<boolean> => {
    const savedPin = await secureStore.getItem('security_pin');
    if (savedPin === pin) {
      setPinLocked(false);
      return true;
    }
    return false;
  };

  const setupPin = async (pin: string) => {
    await secureStore.setItem('security_pin', pin);
    setHasPinSet(true);
    setPinLocked(false);
  };

  const clearPin = async () => {
    await secureStore.removeItem('security_pin');
    setHasPinSet(false);
    setPinLocked(false);
  };

  // Settings
  const saveApiKey = async (key: string) => {
    setApiKey(key);
    await secureStore.setItem('gemini_api_key', key);
  };

  const setAiMode = async (mode: 'simulation' | 'gemini') => {
    setAiModeState(mode);
    await secureStore.setItem('ai_mode', mode);
  };

  const signInWithGoogle = async (email?: string, name?: string) => {
    // Web Platform OAuth Flow
    if (Platform.OS === 'web') {
      if (googleClientId) {
        const redirectUri = encodeURIComponent(window.location.origin);
        const scope = encodeURIComponent('email profile openid');
        const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${googleClientId}&redirect_uri=${redirectUri}&response_type=token&scope=${scope}`;
        window.location.href = authUrl;
        return;
      }

      // Fallback to Web Simulation if no Client ID is present
      const simulatedAccount = {
        name: name || 'Alex Carter',
        email: email || 'alex.carter@gmail.com',
        photoUrl: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
      };
      setUserAccount(simulatedAccount);
      await secureStore.setItem('google_user_session', JSON.stringify(simulatedAccount));
      const list = await db.getProfiles();
      const exists = list.some(p => p.name.toLowerCase() === simulatedAccount.name.toLowerCase());
      if (!exists) {
        await addProfile(simulatedAccount.name, new Date().toISOString().split('T')[0], 'Other', 'Myself');
      }
      return;
    }

    // Mobile Platforms Native Flow
    if (googleClientId) {
      try {
        const { GoogleSignin } = require('@react-native-google-signin/google-signin');
        await GoogleSignin.hasPlayServices();
        const response = await GoogleSignin.signIn();
        const user = response.data?.user || response.user;
        if (!user) throw new Error('No user profile returned from Google Sign-In.');

        const account = {
          name: user.name || 'Google User',
          email: user.email,
          photoUrl: user.photo || undefined,
        };

        setUserAccount(account);
        await secureStore.setItem('google_user_session', JSON.stringify(account));

        const list = await db.getProfiles();
        const exists = list.some(p => p.name.toLowerCase() === account.name.toLowerCase());
        if (!exists) {
          await addProfile(account.name, new Date().toISOString().split('T')[0], 'Other', 'Myself');
        }
        return;
      } catch (err: any) {
        console.error('Google Sign-In Error:', err);
        throw err;
      }
    }

    // Fallback to Mobile Simulation if no Client ID is present
    const simulatedAccount = {
      name: name || 'Alex Carter',
      email: email || 'alex.carter@gmail.com',
      photoUrl: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
    };

    setUserAccount(simulatedAccount);
    await secureStore.setItem('google_user_session', JSON.stringify(simulatedAccount));

    const list = await db.getProfiles();
    const exists = list.some(p => p.name.toLowerCase() === simulatedAccount.name.toLowerCase());
    if (!exists) {
      await addProfile(simulatedAccount.name, new Date().toISOString().split('T')[0], 'Other', 'Myself');
    }
  };

  const signOutGoogle = async () => {
    if (Platform.OS !== 'web' && googleClientId) {
      try {
        const { GoogleSignin } = require('@react-native-google-signin/google-signin');
        await GoogleSignin.signOut();
      } catch (err) {
        console.error('Failed to sign out Google on native:', err);
      }
    }
    setUserAccount(null);
    await secureStore.removeItem('google_user_session');
  };

  const saveGoogleClientId = async (id: string) => {
    setGoogleClientId(id);
    await secureStore.setItem('google_client_id', id);
    if (Platform.OS !== 'web' && id) {
      try {
        const { GoogleSignin } = require('@react-native-google-signin/google-signin');
        GoogleSignin.configure({
          webClientId: id,
          offlineAccess: false,
        });
      } catch (err) {
        console.error('Failed to reconfigure Google Sign-In with new ID:', err);
      }
    }
  };

  // Document & Vitals management
  const addDocument = async (
    filePath: string,
    fileName: string,
    mimeType: string,
    testName: string,
    testDate: string,
    vitalsList: Omit<Vital, 'id' | 'document_id' | 'profile_id' | 'test_date'>[]
  ) => {
    if (!currentProfile) throw new Error('No active profile selected');

    let finalPath = filePath;

    // Persist native mobile files to application document storage
    if (Platform.OS !== 'web') {
      try {
        const { File, Paths } = require('expo-file-system');
        const filename = `${Date.now()}_${fileName}`;
        const sourceFile = new File(filePath);
        const destFile = new File(Paths.document, filename);
        await sourceFile.copy(destFile);
        finalPath = destFile.uri;
      } catch (copyErr) {
        console.error('Failed to copy file to document directory:', copyErr);
      }
    }

    const docId = `doc_${mockService.uuid()}`;
    const newDoc: RecordDocument = {
      id: docId,
      profile_id: currentProfile.id,
      local_path: finalPath,
      mime_type: mimeType,
      upload_date: new Date().toISOString()
    };

    // Save document
    await db.createDocument(newDoc);

    // Save extracted test metadata
    const testId = `test_${mockService.uuid()}`;
    const payload = {
      test_category: testName,
      test_date: testDate,
      vitals: vitalsList
    };

    await db.createExtractedTest({
      id: testId,
      document_id: docId,
      test_name: testName,
      test_date: testDate,
      raw_json_payload: JSON.stringify(payload)
    });

    // Save individual vitals
    for (const v of vitalsList) {
      await db.createVital({
        id: `vital_${mockService.uuid()}`,
        document_id: docId,
        profile_id: currentProfile.id,
        vital_name: v.vital_name,
        value: v.value,
        unit: v.unit,
        reference_range: v.reference_range,
        status: v.status,
        test_date: testDate
      });
    }

    await loadProfileData(currentProfile.id);
  };

  const removeDocument = async (docId: string) => {
    if (!currentProfile) return;
    await db.deleteDocument(docId);
    await loadProfileData(currentProfile.id);
  };

  // Seeds demo health trend history for demonstration
  const seedDemoData = async () => {
    if (!currentProfile) return;

    // Clear current data first
    const currentDocs = await db.getDocuments(currentProfile.id);
    for (const d of currentDocs) {
      await db.deleteDocument(d.id);
    }

    // Generate historical timelines (1 year of lipid, cbc, glucose trends)
    const seeded = mockService.generateHistoricalData(currentProfile.id);

    for (const doc of seeded.documents) {
      await db.createDocument(doc);
    }
    for (const test of seeded.tests) {
      await db.createExtractedTest(test);
    }
    for (const v of seeded.vitals) {
      await db.createVital(v);
    }

    await loadProfileData(currentProfile.id);
  };

  return (
    <AppContext.Provider
      value={{
        profiles,
        currentProfile,
        documents,
        vitals,
        isDbReady,
        pinLocked,
        hasPinSet,
        unlockApp,
        setupPin,
        clearPin,
        apiKey,
        saveApiKey,
        userAccount,
        googleClientId,
        signInWithGoogle,
        signOutGoogle,
        saveGoogleClientId,
        aiMode,
        setAiMode,
        loadProfiles,
        addProfile,
        deleteProfile,
        switchProfile,
        addDocument,
        removeDocument,
        seedDemoData,
        refreshProfileData
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

import { Platform } from 'react-native';

const isWeb = Platform.OS === 'web';

export interface Profile {
  id: string;
  name: string;
  dob: string;
  gender: string;
  relationship: string;
}

export interface RecordDocument {
  id: string;
  profile_id: string;
  local_path: string;
  mime_type: string;
  upload_date: string;
  name?: string; // friendly name
}

export interface ExtractedTest {
  id: string;
  document_id: string;
  test_name: string;
  test_date: string;
  raw_json_payload: string;
}

export interface Vital {
  id: string;
  document_id: string;
  profile_id: string;
  vital_name: string;
  value: number;
  unit: string;
  reference_range: string;
  status: string; // 'Normal' | 'High' | 'Low'
  test_date: string;
}

// Database Connection Interface
export interface DBConnection {
  initialize(): Promise<void>;

  // Profile CRUD
  createProfile(profile: Profile): Promise<void>;
  getProfiles(): Promise<Profile[]>;
  getProfile(id: string): Promise<Profile | null>;
  deleteProfile(id: string): Promise<void>;

  // Document CRUD
  createDocument(doc: RecordDocument): Promise<void>;
  getDocuments(profileId: string): Promise<RecordDocument[]>;
  deleteDocument(id: string): Promise<void>;

  // Extracted Tests
  createExtractedTest(test: ExtractedTest): Promise<void>;
  getExtractedTestByDoc(docId: string): Promise<ExtractedTest | null>;

  // Vitals CRUD
  createVital(vital: Vital): Promise<void>;
  getVitals(profileId: string): Promise<Vital[]>;
  getVitalNames(profileId: string): Promise<string[]>;
  getVitalTrends(profileId: string, vitalName: string): Promise<Vital[]>;
  deleteVitalsByDoc(docId: string): Promise<void>;
}

// ==========================================
// Native SQLite Implementation
// ==========================================
class NativeDBConnection implements DBConnection {
  private db: any = null;

  async getDb() {
    if (this.db) return this.db;
    const SQLite = require('expo-sqlite');
    this.db = await SQLite.openDatabaseAsync('here_vault.db');
    return this.db;
  }

  async initialize(): Promise<void> {
    const db = await this.getDb();

    // Enable Foreign Keys
    await db.execAsync('PRAGMA foreign_keys = ON;');

    // Create Tables
    await db.execAsync(`
      CREATE TABLE IF NOT EXISTS profiles (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        dob TEXT NOT NULL,
        gender TEXT NOT NULL,
        relationship TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS documents (
        id TEXT PRIMARY KEY,
        profile_id TEXT NOT NULL,
        local_path TEXT NOT NULL,
        mime_type TEXT NOT NULL,
        upload_date TEXT NOT NULL,
        FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS extracted_tests (
        id TEXT PRIMARY KEY,
        document_id TEXT NOT NULL,
        test_name TEXT NOT NULL,
        test_date TEXT,
        raw_json_payload TEXT,
        FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS vitals (
        id TEXT PRIMARY KEY,
        document_id TEXT NOT NULL,
        profile_id TEXT NOT NULL,
        vital_name TEXT NOT NULL,
        value REAL NOT NULL,
        unit TEXT NOT NULL,
        reference_range TEXT,
        status TEXT,
        test_date TEXT,
        FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE,
        FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE
      );
    `);
  }

  async createProfile(profile: Profile): Promise<void> {
    const db = await this.getDb();
    await db.runAsync(
      'INSERT OR REPLACE INTO profiles (id, name, dob, gender, relationship) VALUES (?, ?, ?, ?, ?)',
      profile.id,
      profile.name,
      profile.dob,
      profile.gender,
      profile.relationship
    );
  }

  async getProfiles(): Promise<Profile[]> {
    const db = await this.getDb();
    return await db.getAllAsync('SELECT * FROM profiles');
  }

  async getProfile(id: string): Promise<Profile | null> {
    const db = await this.getDb();
    const result = await db.getFirstAsync('SELECT * FROM profiles WHERE id = ?', id);
    return result || null;
  }

  async deleteProfile(id: string): Promise<void> {
    const db = await this.getDb();
    await db.runAsync('DELETE FROM profiles WHERE id = ?', id);
  }

  async createDocument(doc: RecordDocument): Promise<void> {
    const db = await this.getDb();
    await db.runAsync(
      'INSERT OR REPLACE INTO documents (id, profile_id, local_path, mime_type, upload_date) VALUES (?, ?, ?, ?, ?)',
      doc.id,
      doc.profile_id,
      doc.local_path,
      doc.mime_type,
      doc.upload_date
    );
  }

  async getDocuments(profileId: string): Promise<RecordDocument[]> {
    const db = await this.getDb();
    return await db.getAllAsync('SELECT * FROM documents WHERE profile_id = ? ORDER BY upload_date DESC', profileId);
  }

  async deleteDocument(id: string): Promise<void> {
    const db = await this.getDb();
    await db.runAsync('DELETE FROM documents WHERE id = ?', id);
  }

  async createExtractedTest(test: ExtractedTest): Promise<void> {
    const db = await this.getDb();
    await db.runAsync(
      'INSERT OR REPLACE INTO extracted_tests (id, document_id, test_name, test_date, raw_json_payload) VALUES (?, ?, ?, ?, ?)',
      test.id,
      test.document_id,
      test.test_name,
      test.test_date,
      test.raw_json_payload
    );
  }

  async getExtractedTestByDoc(docId: string): Promise<ExtractedTest | null> {
    const db = await this.getDb();
    const result = await db.getFirstAsync('SELECT * FROM extracted_tests WHERE document_id = ?', docId);
    return result || null;
  }

  async createVital(vital: Vital): Promise<void> {
    const db = await this.getDb();
    await db.runAsync(
      'INSERT OR REPLACE INTO vitals (id, document_id, profile_id, vital_name, value, unit, reference_range, status, test_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
      vital.id,
      vital.document_id,
      vital.profile_id,
      vital.vital_name,
      vital.value,
      vital.unit,
      vital.reference_range,
      vital.status,
      vital.test_date
    );
  }

  async getVitals(profileId: string): Promise<Vital[]> {
    const db = await this.getDb();
    return await db.getAllAsync('SELECT * FROM vitals WHERE profile_id = ? ORDER BY test_date DESC', profileId);
  }

  async getVitalNames(profileId: string): Promise<string[]> {
    const db = await this.getDb();
    const results = await db.getAllAsync('SELECT DISTINCT vital_name FROM vitals WHERE profile_id = ?', profileId) as { vital_name: string }[];
    return results.map(r => r.vital_name);
  }

  async getVitalTrends(profileId: string, vitalName: string): Promise<Vital[]> {
    const db = await this.getDb();
    return await db.getAllAsync(
      'SELECT * FROM vitals WHERE profile_id = ? AND vital_name = ? ORDER BY test_date ASC',
      profileId,
      vitalName
    );
  }

  async deleteVitalsByDoc(docId: string): Promise<void> {
    const db = await this.getDb();
    await db.runAsync('DELETE FROM vitals WHERE document_id = ?', docId);
  }
}

// ==========================================
// Web Mock DB Implementation
// ==========================================
class WebDBConnection implements DBConnection {
  private profiles: Profile[] = [];
  private documents: RecordDocument[] = [];
  private extractedTests: ExtractedTest[] = [];
  private vitals: Vital[] = [];

  private loadFromStorage() {
    try {
      this.profiles = JSON.parse(localStorage.getItem('here_profiles') || '[]');
      this.documents = JSON.parse(localStorage.getItem('here_documents') || '[]');
      this.extractedTests = JSON.parse(localStorage.getItem('here_extracted_tests') || '[]');
      this.vitals = JSON.parse(localStorage.getItem('here_vitals') || '[]');
    } catch (e) {
      console.warn('Failed to load DB from localStorage', e);
    }
  }

  private saveToStorage() {
    try {
      localStorage.setItem('here_profiles', JSON.stringify(this.profiles));
      localStorage.setItem('here_documents', JSON.stringify(this.documents));
      localStorage.setItem('here_extracted_tests', JSON.stringify(this.extractedTests));
      localStorage.setItem('here_vitals', JSON.stringify(this.vitals));
    } catch (e) {
      console.warn('Failed to save DB to localStorage', e);
    }
  }

  async initialize(): Promise<void> {
    this.loadFromStorage();
  }

  async createProfile(profile: Profile): Promise<void> {
    this.profiles = this.profiles.filter(p => p.id !== profile.id);
    this.profiles.push(profile);
    this.saveToStorage();
  }

  async getProfiles(): Promise<Profile[]> {
    return [...this.profiles];
  }

  async getProfile(id: string): Promise<Profile | null> {
    return this.profiles.find(p => p.id === id) || null;
  }

  async deleteProfile(id: string): Promise<void> {
    this.profiles = this.profiles.filter(p => p.id !== id);
    this.documents = this.documents.filter(d => d.profile_id !== id);
    this.vitals = this.vitals.filter(v => v.profile_id !== id);
    this.saveToStorage();
  }

  async createDocument(doc: RecordDocument): Promise<void> {
    this.documents = this.documents.filter(d => d.id !== doc.id);
    this.documents.push(doc);
    this.saveToStorage();
  }

  async getDocuments(profileId: string): Promise<RecordDocument[]> {
    return this.documents
      .filter(d => d.profile_id === profileId)
      .sort((a, b) => b.upload_date.localeCompare(a.upload_date));
  }

  async deleteDocument(id: string): Promise<void> {
    this.documents = this.documents.filter(d => d.id !== id);
    this.extractedTests = this.extractedTests.filter(e => e.document_id !== id);
    this.vitals = this.vitals.filter(v => v.document_id !== id);
    this.saveToStorage();
  }

  async createExtractedTest(test: ExtractedTest): Promise<void> {
    this.extractedTests = this.extractedTests.filter(e => e.id !== test.id);
    this.extractedTests.push(test);
    this.saveToStorage();
  }

  async getExtractedTestByDoc(docId: string): Promise<ExtractedTest | null> {
    return this.extractedTests.find(e => e.document_id === docId) || null;
  }

  async createVital(vital: Vital): Promise<void> {
    this.vitals = this.vitals.filter(v => v.id !== vital.id);
    this.vitals.push(vital);
    this.saveToStorage();
  }

  async getVitals(profileId: string): Promise<Vital[]> {
    return this.vitals
      .filter(v => v.profile_id === profileId)
      .sort((a, b) => b.test_date.localeCompare(a.test_date));
  }

  async getVitalNames(profileId: string): Promise<string[]> {
    const names = this.vitals
      .filter(v => v.profile_id === profileId)
      .map(v => v.vital_name);
    return Array.from(new Set(names));
  }

  async getVitalTrends(profileId: string, vitalName: string): Promise<Vital[]> {
    return this.vitals
      .filter(v => v.profile_id === profileId && v.vital_name.toLowerCase() === vitalName.toLowerCase())
      .sort((a, b) => a.test_date.localeCompare(b.test_date));
  }

  async deleteVitalsByDoc(docId: string): Promise<void> {
    this.vitals = this.vitals.filter(v => v.document_id !== docId);
    this.saveToStorage();
  }
}

export const db: DBConnection = isWeb ? new WebDBConnection() : new NativeDBConnection();
export default db;

