// ==========================================
export const AuthPINScreen: React.FC = () => {
  const { unlockApp, currentProfile } = useApp();
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handlePressNumber = (num: string) => {
    if (pin.length < 4) {
      setError(false);
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        // Trigger verification
        setTimeout(async () => {
          const success = await unlockApp(newPin);
          if (!success) {
            setError(true);
            setPin('');
          }
        }, 150);
      }
    }
  };

  const handleBackspace = () => {
    setPin(pin.slice(0, -1));
  };

  return (
    <View style={styles.authContainer}>
      <View style={styles.authHeader}>
        <View style={styles.logoCircle}>
          <Brain size={48} color={COLORS.primaryLight} />
        </View>
        <Text style={styles.authTitle}>HeRe Vault</Text>
        <Text style={styles.authSubtitle}>Health Registry Secure Local Lock</Text>
      </View>

      <View style={styles.pinDisplayContainer}>
        <Text style={styles.pinPrompt}>Enter security PIN to unlock vault</Text>
        <View style={styles.dotsRow}>
          {[0, 1, 2, 3].map((index) => (
            <View
              key={index}
              style={[
                styles.pinDot,
                pin.length > index && styles.pinDotFilled,
                error && styles.pinDotError
              ]}
            />
          ))}
        </View>
        {error && <Text style={styles.pinErrorText}>Invalid PIN code. Try again.</Text>}
      </View>

      {/* Grid Keyboard */}
      <View style={styles.keyboard}>
        {[['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9']].map((row, rIdx) => (
          <View key={rIdx} style={styles.keyboardRow}>
            {row.map((num) => (
              <TouchableOpacity
                key={num}
                style={styles.keyButton}
                onPress={() => handlePressNumber(num)}
              >
                <Text style={styles.keyButtonText}>{num}</Text>
              </TouchableOpacity>
            ))}
          </View>
        ))}
        <View style={styles.keyboardRow}>
          <View style={styles.keyButtonEmpty} />
          <TouchableOpacity
            style={styles.keyButton}
            onPress={() => handlePressNumber('0')}
