export const ProfileManageScreen: React.FC<{
  onBack: () => void;
}> = ({ onBack }) => {
  const { profiles, addProfile, deleteProfile, currentProfile, switchProfile } = useApp();
  const [name, setName] = useState('');
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('Male');
  const [relationship, setRelationship] = useState('Myself');

  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!name.trim() || !dob.trim()) {
      Alert.alert('Required fields', 'Please enter Name and Date of Birth');
      return;
    }
    // Verify dob format YYYY-MM-DD
    const dobRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dobRegex.test(dob)) {
      Alert.alert('Date format error', 'Please enter date in YYYY-MM-DD format');
      return;
    }

    setSubmitting(true);
    try {
      await addProfile(name, dob, gender, relationship);
      setName('');
      setDob('');
      setGender('Male');
      setRelationship('Myself');
      Alert.alert('Success', 'Profile created successfully');
      onBack();
    } catch (e) {
      Alert.alert('Error', 'Failed to create profile');
    } finally {
      setSubmitting(false);
    }
  };

  const handleSelectProfile = async (id: string) => {
    await switchProfile(id);
    onBack();
  };

  const handleDelete = (id: string, profileName: string) => {
    if (profiles.length <= 1) {
      Alert.alert('Alert', 'At least one profile must exist.');
      return;
    }
    Alert.alert(
      'Delete Profile',
      `Are you sure you want to permanently delete profile "${profileName}" and all associated medical data? This cannot be undone.`,
      [
        { text: 'Cancel', style: 'cancel' },
        { 
          text: 'Delete', 
          style: 'destructive',
          onPress: async () => {
            await deleteProfile(id);
          }
        }
      ]
    );
  };

  return (
    <ScrollView style={styles.screenScroll} contentContainerStyle={styles.screenContent}>
      <TouchableOpacity style={styles.backLink} onPress={onBack}>
        <ArrowLeft size={16} color={COLORS.primaryLight} />
