      <Text style={styles.pageTitle}>Profile Management</Text>

      {/* Current Profiles List */}
      <Text style={styles.sectionTitle}>Existing Profiles</Text>
      <View style={styles.profileSectionList}>
        {profiles.map((p) => {
          const isActive = currentProfile && currentProfile.id === p.id;
          return (
            <View key={p.id} style={[styles.profileListItem, isActive && styles.profileListItemActive]}>
              <TouchableOpacity 
                style={styles.profileListItemClickable}
