export const DocumentUploadScreen: React.FC<{
  onBack: () => void;
}> = ({ onBack }) => {
  const { addDocument, currentProfile, apiKey, aiMode } = useApp();
  const { width } = useWindowDimensions();
  const [docDate, setDocDate] = useState(new Date().toISOString().split('T')[0]);
  const [uploading, setUploading] = useState(false);
  const [extractedResults, setExtractedResults] = useState<{
    fileUri: string;
    fileName: string;
    mimeType: string;
    test_category: string;
    test_date: string;
    vitals: {
      name: string;
      value: number;
      unit: string;
      reference_range: string;
      status: string;
    }[];
  }[]>([]);
  const [progressLogs, setProgressLogs] = useState<string[]>([]);

  // Selected files details state array
  const [selectedFiles, setSelectedFiles] = useState<{
    uri: string;
    name: string;
    mimeType: string;
    size: number;
    fileObject?: any; // For Web File object
  }[]>([]);
  const [errorText, setErrorText] = useState<string | null>(null);

  const [isStep1Expanded, setIsStep1Expanded] = useState(true);
  const [expandedFileIndices, setExpandedFileIndices] = useState<number[]>([0]);
  const [isStep2Expanded, setIsStep2Expanded] = useState(false);

  // Web camera state parameters
  const [showWebCamera, setShowWebCamera] = useState(false);
  const videoRef = React.useRef<HTMLVideoElement | null>(null);
  const [cameraStream, setCameraStream] = useState<MediaStream | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  const startWebCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      });
      setCameraStream(stream);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (e: any) {
      console.error('Webcam Access Error:', e);
      setCameraError('Unable to access camera. Please check browser permissions.');
    }
  };

  const stopWebCamera = () => {
    if (cameraStream) {
      cameraStream.getTracks().forEach(track => track.stop());
      setCameraStream(null);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const video = videoRef.current;
      const canvas = document.createElement('canvas');

      const videoHeight = video.videoHeight || 480;
      const videoWidth = video.videoWidth || 640;

      // Calculate coordinates to extract a 3:4 portrait crop from the center of the video
      const sHeight = videoHeight;
      const sWidth = videoHeight * (3 / 4);
      const sx = (videoWidth - sWidth) / 2;
      const sy = 0;

      canvas.width = 600;
      canvas.height = 800; // 3:4 aspect ratio portrait

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, sx, sy, sWidth, sHeight, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const base64 = dataUrl.split(',')[1];

        setSelectedFiles(prev => [
          ...prev,
          {
            uri: dataUrl,
            name: `scan_${Date.now()}.jpg`,
            mimeType: 'image/jpeg',
            size: Math.round(base64.length * 0.75),
            fileObject: null
          }
        ]);

        stopWebCamera();
        setShowWebCamera(false);
      }
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return 'N/A';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  const handlePickDocument = async () => {
    try {
      const result = await DocumentPicker.getDocumentAsync({
        type: ['application/pdf', 'text/plain', 'image/*'],
        copyToCacheDirectory: true,
        multiple: true,
      });

      if (result.canceled || !result.assets || result.assets.length === 0) {
        return;
      }

      const filesToAdd: typeof selectedFiles = [];

      for (const asset of result.assets) {
        let finalUri = asset.uri;

        // On Web, read files into persistent base64 data URLs to prevent blob expiration on reload
        if (Platform.OS === 'web' && asset.file) {
          finalUri = await new Promise<string>((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result as string);
            reader.onerror = reject;
            reader.readAsDataURL(asset.file!);
          });
        }

        filesToAdd.push({
          uri: finalUri,
          name: asset.name,
          mimeType: asset.mimeType || 'application/octet-stream',
          size: asset.size || 0,
          fileObject: asset.file // Web only
