            }
          } else {
            // PDF or Image base64
            if (file.uri.startsWith('data:')) {
              fileContent.base64Image = file.uri.split(',')[1];
            } else if (file.fileObject) {
              const base64 = await new Promise<string>((resolve, reject) => {
