import { secureStore } from './secureStore';
import { Vital, db } from '../db/db';
import { mockService } from './mockService';
import { Platform } from 'react-native';

const GEMINI_API_URL = 'https://generativelanguage.googleapis.com/v1/models/gemini-1.5-flash:generateContent';

async function fetchWithRetry(
  url: string, 
  options: RequestInit, 
  retries = 3, 
  delayMs = 1500, 
  log?: (msg: string) => void
): Promise<Response> {
  for (let i = 0; i < retries; i++) {
    try {
      const response = await fetch(url, options);
      if (response.status === 429 || response.status === 503) {
        const attempt = i + 1;
        const msg = `[WARN] Received HTTP ${response.status} (Rate Limited/High Demand). Retrying attempt ${attempt}/${retries} in ${delayMs}ms...`;
        if (log) log(msg);
        console.warn(msg);
        await new Promise(resolve => setTimeout(resolve, delayMs));
        delayMs *= 2;
        continue;
      }
      return response;
    } catch (err: any) {
      if (i === retries - 1) throw err;
      const attempt = i + 1;
      const msg = `[WARN] Request failed: ${err.message || err}. Retrying attempt ${attempt}/${retries} in ${delayMs}ms...`;
      if (log) log(msg);
      console.warn(msg);
      await new Promise(resolve => setTimeout(resolve, delayMs));
      delayMs *= 2;
    }
  }
  throw new Error('Retries exhausted');
}

export interface AIResult {
  test_category: string;
  test_date: string;
  vitals: {
    name: string;
    value: number;
    unit: string;
    reference_range: string;
    status: 'Normal' | 'High' | 'Low';
  }[];
}

export const aiService = {

  // Check if Gemini API key is configured
  async hasApiKey(): Promise<boolean> {
    const key = process.env.EXPO_PUBLIC_GEMINI_API_KEY;
    return !!key && key.trim().length > 0;
  },

  // Strip PII from text input (e.g. names, phone numbers)
  scrubPII(text: string): string {
    let scrubbed = text;

    // Scrub typical phone numbers
    scrubbed = scrubbed.replace(/\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/g, '[PHONE]');

    // Scrub emails
    scrubbed = scrubbed.replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL]');

    // Scrub potential SSN / national IDs
    scrubbed = scrubbed.replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[ID]');

    return scrubbed;
  },

  // Parse Document using Gemini, local SLM, or mock fallback
  async parseDocument(
    profileId: string,
    fileContent: { textContent?: string; base64Image?: string; fileName: string; mimeType: string },
    onLog?: (message: string) => void
  ): Promise<AIResult> {
    const log = (msg: string) => {
      console.log(msg);
      if (onLog) onLog(msg);
    };

    const savedAiMode = await secureStore.getItem('ai_mode') || 'simulation';

    let apiKey = process.env.EXPO_PUBLIC_GEMINI_API_KEY || '';
    if (!apiKey) {
      apiKey = await secureStore.getItem('gemini_api_key') || '';
    }
    const isMockMode = savedAiMode === 'simulation' || (!apiKey || apiKey.trim() === '');

    if (isMockMode) {
      log('[INFO] Gemini API key not found or running in simulation mode. Running in simulation mode.');
      await new Promise(resolve => setTimeout(resolve, 600));

      // Determine template to return based on filename or text content
      const lowerName = fileContent.fileName.toLowerCase();
      const lowerText = (fileContent.textContent || '').toLowerCase();

      let templateKey: 'cbc' | 'lipid' | 'thyroid' | 'metabolic' = 'cbc';
      if (lowerName.includes('lipid') || lowerName.includes('cholesterol') || lowerText.includes('lipid') || lowerText.includes('cholesterol')) {
        templateKey = 'lipid';
      } else if (lowerName.includes('thyroid') || lowerName.includes('tsh') || lowerText.includes('thyroid') || lowerText.includes('tsh')) {
        templateKey = 'thyroid';
      } else if (lowerName.includes('metabolic') || lowerName.includes('glucose') || lowerText.includes('glucose') || lowerText.includes('hba1c')) {
        templateKey = 'metabolic';
      }

      log(`[INFO] Matching simulated template found: ${templateKey.toUpperCase()}`);
      await new Promise(resolve => setTimeout(resolve, 800));

      log('[INFO] Extracting simulated biomarkers and reference ranges...');
      const simulated = mockService.simulateReportUpload(profileId, templateKey);
      const parsed = JSON.parse(simulated.test.raw_json_payload);

      await new Promise(resolve => setTimeout(resolve, 600));
      log('[SUCCESS] Simulated clinical data extraction completed.');

      return {
        test_category: parsed.test_category,
        test_date: parsed.test_date,
        vitals: parsed.vitals
      };
    }

    log('[INFO] Initializing OCR extraction pipeline...');
    log('[INFO] Scrubbing patient PII logs for maximum security...');

    // Call actual Gemini API
    const systemPrompt = `You are an expert clinical data extraction assistant. Parse this medical lab report text/image and output a structured JSON object.
Strip out any Personal Identifiable Information (PII) such as patient names, addresses, phone numbers, or emails.
Compare extracted vital values against their reference ranges to categorize status: 'Normal', 'High', or 'Low'.
Extract the date when the lab test was performed as 'test_date' in strict YYYY-MM-DD format (if the date is not found in the report, default to today's date).

Return ONLY a JSON object matching this schema. All property values, including biomarker numbers and ranges, MUST be wrapped in double quotes as strings to ensure valid JSON syntax:
{
  "test_category": "Complete Blood Count, Lipid Profile, Thyroid Panel, Prescription, etc.",
  "test_date": "YYYY-MM-DD",
  "vitals": [
    {
      "name": "Biomarker / Vital name (e.g. Hemoglobin, LDL Cholesterol, TSH, Glucose)",
      "value": "12.5",
      "unit": "g/dL, mg/dL, etc.",
      "reference_range": "e.g. 12.0 - 16.0",
      "status": "Normal"
    }
  ]
}`;

    const contents: any[] = [];

    // Add text contents if available
    let textToSend = `Report File Name: ${fileContent.fileName}\n`;
    if (fileContent.textContent) {
      textToSend += `Content:\n${this.scrubPII(fileContent.textContent)}`;
    }

    const textPart = { text: textToSend };

    if (fileContent.base64Image) {
      // Multimodal image upload
      contents.push({
        parts: [
          textPart,
          {
            inlineData: {
              mimeType: fileContent.mimeType || 'image/jpeg',
              data: fileContent.base64Image
            }
          },
          { text: systemPrompt }
        ]
      });
    } else {
      // Text-only upload
      contents.push({
        parts: [
          textPart,
          { text: systemPrompt }
        ]
      });
    }

    const modelsToTry = [
      'gemini-1.5-flash',
      'gemini-2.0-flash',
      'gemini-1.5-flash-8b',
      'gemini-1.5-pro'
    ];

    let lastError = null;

    const errorsList: string[] = [];

    for (const model of modelsToTry) {
      log(`[INFO] Connecting to Gemini API (Model: ${model})...`);
      const url = `https://generativelanguage.googleapis.com/v1/models/${model}:generateContent?key=${apiKey}`;

      try {
        const response = await fetchWithRetry(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            contents,
            generationConfig: {
              responseMimeType: 'application/json',
              temperature: 0.1
            }
          })
        }, 3, 1500, log);

        if (!response.ok) {
          const errText = await response.text();
          throw new Error(`HTTP ${response.status}: ${errText}`);
        }

        log(`[SUCCESS] Connection established. Processing response from ${model}...`);
        const resJson = await response.json();
        const textResponse = resJson.candidates?.[0]?.content?.parts?.[0]?.text;

        if (!textResponse) {
          throw new Error('Received empty text response from model candidates');
        }

        log('[INFO] Sanitizing and parsing extracted clinical JSON...');
        const cleanText = cleanJsonString(textResponse);

        try {
          const parsed = JSON.parse(cleanText) as AIResult;
          log('[SUCCESS] Biomarkers and test metadata extracted successfully.');
          return parsed;
        } catch (parseErr: any) {
          console.error('Failed to parse clean text:', cleanText);
          throw new Error(`JSON parsing failed: ${parseErr.message}`);
        }
      } catch (err: any) {
        const errorMsg = err.message || String(err);
        log(`[WARN] Model ${model} failed: ${errorMsg}`);
        errorsList.push(`${model}: ${errorMsg}`);
        lastError = err;
      }
    }

    const compiledErrors = errorsList.join('; ');
    throw new Error(`All Gemini API models failed. Details: ${compiledErrors}`);
  },

