function cleanJsonString(raw: string): string {
  let cleaned = raw.trim();

  // Remove markdown code block wraps
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\n?/i, '');
    cleaned = cleaned.replace(/\n?```$/, '');
    cleaned = cleaned.trim();
  }

  // Remove single line comments (// ...) safely
  cleaned = cleaned.split('\n')
    .map(line => {
      const commentIndex = line.indexOf('//');
      if (commentIndex !== -1) {
        const before = line.substring(0, commentIndex);
        if (!before.includes('http:') && !before.includes('https:')) {
          return before;
        }
      }
      return line;
    })
    .join('\n');

  // Remove block comments (/* ... */)
  cleaned = cleaned.replace(/\/\*[\s\S]*?\*\//g, '');

  // Wrap unquoted value string values in double quotes
  cleaned = cleaned.replace(/(?:"value"|'value')\s*:\s*([^",'{\[\]}\n]+)/g, (match, valStr) => {
    const trimmedVal = valStr.trim();
    if (isNaN(Number(trimmedVal))) {
      const escaped = trimmedVal.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
      return `"value": "${escaped}"`;
    }
    return match;
  });

  // Remove trailing commas before closing braces/brackets
  cleaned = cleaned.replace(/,\s*([}\]])/g, '$1');

  return cleaned.trim();
}

import { Alert as RNAlert, Platform } from 'react-native';

export const Alert = {
  alert: (
    title: string,
    message?: string,
    buttons?: Array<{ text?: string; onPress?: () => void; style?: 'default' | 'cancel' | 'destructive' }>,
    options?: any
  ) => {
    if (Platform.OS === 'web') {
      if (buttons && buttons.length > 0) {
        // If there's only one button, treat it like an alert
        if (buttons.length === 1) {
          window.alert(`${title}\n\n${message || ''}`);
          if (buttons[0].onPress) {
            buttons[0].onPress();
          }
          return;
        }

        // Otherwise, simulate a confirm box
        const confirmText = `${title}\n\n${message || ''}`;
        const confirmResult = window.confirm(confirmText);

        if (confirmResult) {
          // Trigger first button that is not 'cancel' (e.g. default or destructive)
          const primaryBtn = buttons.find(b => b.style !== 'cancel') || buttons[0];
          if (primaryBtn && primaryBtn.onPress) {
            primaryBtn.onPress();
          }
        } else {
          // Trigger cancel action if user clicks cancel/no
          const cancelBtn = buttons.find(b => b.style === 'cancel');
          if (cancelBtn && cancelBtn.onPress) {
            cancelBtn.onPress();
          }
        }
      } else {
        window.alert(`${title}\n\n${message || ''}`);
      }
    } else {
      RNAlert.alert(title, message, buttons, options);
    }
  }
};

