export const mockService = {
  // Generate random IDs
  uuid(): string {
    return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
  },

  // Generates dummy records spread over several months for a profile to demonstrate trending
  generateHistoricalData(profileId: string): { documents: RecordDocument[], tests: ExtractedTest[], vitals: Vital[] } {
    const documents: RecordDocument[] = [];
    const tests: ExtractedTest[] = [];
    const vitals: Vital[] = [];

    const now = new Date();

    // We create trend logs for 12 months ago, 6 months ago, 3 months ago, and today.
    const intervals = [
      { monthsAgo: 12, glucose: 118, ldl: 155, hemoglobin: 11.2, tsh: 5.8 },
      { monthsAgo: 6, glucose: 112, ldl: 145, hemoglobin: 12.5, tsh: 5.2 },
      { monthsAgo: 3, glucose: 105, ldl: 138, hemoglobin: 13.1, tsh: 4.9 },
      { monthsAgo: 0, glucose: 98, ldl: 122, hemoglobin: 13.9, tsh: 3.8 } // improving trends!
    ];

    intervals.forEach(interval => {
      const docDate = new Date(now.getFullYear(), now.getMonth() - interval.monthsAgo, now.getDate() - 2);
      const dateStr = docDate.toISOString().split('T')[0];
      const docId = `doc_${this.uuid()}`;

      // 1. Create Consolidated Health Document
      documents.push({
        id: docId,
        profile_id: profileId,
        local_path: `file:///simulated/documents/health_report_${interval.monthsAgo}m.pdf`,
        mime_type: 'application/pdf',
        upload_date: docDate.toISOString()
      });

      // 2. Extracted Test Info
      const testId = `test_${this.uuid()}`;
      const mockPayload = {
        test_category: 'Consolidated Metabolic & Lipid Profile',
        test_date: dateStr,
        vitals: [
          { name: 'Blood Glucose', value: interval.glucose, unit: 'mg/dL', reference_range: '70 - 99', status: interval.glucose > 99 ? 'High' : 'Normal' },
          { name: 'LDL Cholesterol', value: interval.ldl, unit: 'mg/dL', reference_range: '< 100', status: interval.ldl > 100 ? 'High' : 'Normal' },
          { name: 'Hemoglobin', value: interval.hemoglobin, unit: 'g/dL', reference_range: '12.0 - 16.0', status: interval.hemoglobin < 12.0 ? 'Low' : 'Normal' },
          { name: 'TSH', value: interval.tsh, unit: 'uIU/mL', reference_range: '0.45 - 4.50', status: interval.tsh > 4.50 ? 'High' : 'Normal' }
        ]
      };

      tests.push({
        id: testId,
        document_id: docId,
        test_name: 'Consolidated Health Panel',
        test_date: dateStr,
        raw_json_payload: JSON.stringify(mockPayload)
      });

      // 3. Add individual Vitals
      mockPayload.vitals.forEach(v => {
        vitals.push({
          id: `vital_${this.uuid()}`,
          document_id: docId,
          profile_id: profileId,
          vital_name: v.name,
          value: v.value,
          unit: v.unit,
          reference_range: v.reference_range,
          status: v.status,
          test_date: dateStr
        });
      });
    });

    return { documents, tests, vitals };
  },

  // Generates single report upload simulation
  simulateReportUpload(profileId: string, templateKey: keyof typeof MOCK_TEMPLATES, dateStr?: string): { document: RecordDocument, test: ExtractedTest, vitals: Vital[] } {
    const template = MOCK_TEMPLATES[templateKey];
    const docId = `doc_${this.uuid()}`;
    const testId = `test_${this.uuid()}`;
    const uploadDateStr = dateStr || new Date().toISOString().split('T')[0];
    const isoString = dateStr ? new Date(dateStr).toISOString() : new Date().toISOString();

    const document: RecordDocument = {
      id: docId,
      profile_id: profileId,
      local_path: `file:///simulated/documents/${templateKey}_report_${this.uuid().substring(0, 5)}.pdf`,
      mime_type: 'application/pdf',
      upload_date: isoString
    };

    const payload = {
      test_category: template.category,
      test_date: uploadDateStr,
      vitals: template.vitals.map(v => ({
        name: v.vital_name,
        value: v.value,
        unit: v.unit,
        reference_range: v.reference_range,
        status: v.status
      }))
    };

    const test: ExtractedTest = {
      id: testId,
      document_id: docId,
      test_name: template.name,
      test_date: uploadDateStr,
      raw_json_payload: JSON.stringify(payload)
    };

    const vitalsList: Vital[] = template.vitals.map(v => ({
      id: `vital_${this.uuid()}`,
      document_id: docId,
      profile_id: profileId,
      vital_name: v.vital_name,
      value: v.value,
      unit: v.unit,
      reference_range: v.reference_range,
      status: v.status,
      test_date: uploadDateStr
    }));

    return { document, test, vitals: vitalsList };
  }
};

import * as SecureStore from 'expo-secure-store';
import { Platform } from 'react-native';

const isWeb = Platform.OS === 'web';

// Simulated storage in-memory for fallback if localStorage is disabled or fails
const memoryStorage: Record<string, string> = {};

export const secureStore = {
  async setItem(key: string, value: string): Promise<void> {
    if (isWeb) {
      try {
        localStorage.setItem(key, value);
      } catch (e) {
        memoryStorage[key] = value;
      }
      return;
    }
    try {
      await SecureStore.setItemAsync(key, value);
    } catch (e) {
      console.warn('Failed to set secure store value, falling back to memory', e);
      memoryStorage[key] = value;
    }
  },

  async getItem(key: string): Promise<string | null> {
    if (isWeb) {
      try {
        return localStorage.getItem(key);
      } catch (e) {
        return memoryStorage[key] || null;
      }
    }
    try {
      return await SecureStore.getItemAsync(key);
    } catch (e) {
      console.warn('Failed to get secure store value, falling back to memory', e);
      return memoryStorage[key] || null;
    }
  },

  async removeItem(key: string): Promise<void> {
    if (isWeb) {
      try {
        localStorage.removeItem(key);
      } catch (e) {
        delete memoryStorage[key];
      }
      return;
    }
    try {
      await SecureStore.deleteItemAsync(key);
    } catch (e) {
      console.warn('Failed to delete secure store value, falling back to memory', e);
      delete memoryStorage[key];
    }
  }
};

