import React, { useState } from 'react';
import { View, Text, StyleSheet, SafeAreaView, StatusBar, ActivityIndicator, TextInput, TouchableOpacity, ScrollView, Platform, Image } from 'react-native';
import { Alert } from './src/services/alert';
import { Brain, Lock, User, Plus, LogOut } from 'lucide-react-native';
import { AppProvider, useApp } from './src/context/AppContext';
import { COLORS, BORDER_RADIUS, SPACING } from './src/styles/theme';
import {
  NavBar,
  AuthPINScreen,
  DashboardScreen,
  ProfileManageScreen,
  DocumentUploadScreen,
  DocumentListScreen,
  DocumentDetailScreen,
  TrendsScreen,
  AIInsightsScreen,
  SettingsScreen,
  PINSetupScreen,
  LoginScreen
} from './src/screens/Screens';

// ==========================================
// Onboarding Screen (if no profiles exist)
// ==========================================
const OnboardingScreen: React.FC = () => {
  const { addProfile } = useApp();
  const [name, setName] = useState('');
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('Male');
  const [relationship, setRelationship] = useState('Myself');
  const [loading, setLoading] = useState(false);

  const handleCreate = async () => {
    if (!name.trim() || !dob.trim()) {
      Alert.alert('Required fields', 'Please enter Name and Date of Birth');
      return;
    }
    // Verify dob format YYYY-MM-DD
    const dobRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dobRegex.test(dob)) {
      Alert.alert('Date format error', 'Please enter date in YYYY-MM-DD format');
      return;
    }
    setLoading(true);
    try {
      await addProfile(name, dob, gender, relationship);
    } catch (e) {
      Alert.alert('Error', 'Failed to create profile');
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView style={styles.scroll} contentContainerStyle={styles.scrollContent}>
      <View style={styles.logoBox}>
        <Brain size={28} color={COLORS.primaryLight} />
        <View style={styles.logoTextWrapper}>
          <Text style={styles.welcomeTitle}>HeRe Vault</Text>
          <Text style={styles.welcomeSub}>Clinical Registry & Health Ledger</Text>
        </View>
      </View>

      <View style={styles.formPaneWrapper}>
        <Text style={styles.sectionTitle}>Create Patient Profile</Text>
        <View style={styles.card}>
          <Text style={styles.label}>Full Name</Text>
          <TextInput
            style={styles.input}
            placeholder="e.g. Alex Carter"
            placeholderTextColor={COLORS.textMuted}
            value={name}
            onChangeText={setName}
          />

          <Text style={styles.label}>Date of Birth</Text>
          {Platform.OS === 'web' ? (
            <input
              type="date"
              value={dob}
              onChange={(e) => setDob(e.target.value)}
              style={{
                backgroundColor: COLORS.background,
                border: `1px solid ${COLORS.cardBorder}`,
                borderRadius: BORDER_RADIUS.md,
                padding: '8px 12px',
                color: COLORS.textLight,
                colorScheme: 'dark',
                fontSize: 13,
                marginBottom: SPACING.md,
                outline: 'none',
                width: '100%',
                height: 40,
                boxSizing: 'border-box',
                fontFamily: 'inherit'
              }}
            />
          ) : (
            <TextInput
              style={styles.input}
              placeholder="e.g. 1992-08-15"
              placeholderTextColor={COLORS.textMuted}
              value={dob}
              onChangeText={setDob}
            />
          )}

          <Text style={styles.label}>Gender</Text>
          <View style={styles.pillRow}>
            {['Male', 'Female', 'Other'].map((g) => (
              <TouchableOpacity
                key={g}
                style={[styles.pill, gender === g && styles.pillActive]}
                onPress={() => setGender(g)}
              >
                <Text style={[styles.pillText, gender === g && styles.pillTextActive]}>{g}</Text>
              </TouchableOpacity>
            ))}
          </View>

          <Text style={styles.label}>Relationship</Text>
          <View style={styles.pillRow}>
            {['Myself', 'Mother', 'Father', 'Spouse', 'Child'].map((r) => (
              <TouchableOpacity
                key={r}
                style={[styles.pill, relationship === r && styles.pillActive]}
                onPress={() => setRelationship(r)}
              >
                <Text style={[styles.pillText, relationship === r && styles.pillTextActive]}>{r}</Text>
              </TouchableOpacity>
            ))}
          </View>

          <TouchableOpacity 
            style={styles.btn} 
            onPress={handleCreate}
            disabled={loading}
          >
            {loading ? (
              <ActivityIndicator size="small" color={COLORS.textLight} />
            ) : (
              <>
                <Plus size={18} color={COLORS.textLight} />
                <Text style={styles.btnText}>Initialise Vault</Text>
              </>
            )}
          </TouchableOpacity>
        </View>
      </View>
    </ScrollView>
  );
};

// ==========================================
// Inner Application router switcher shell
// ==========================================
const AppContent: React.FC = () => {
  const { isDbReady, profiles, pinLocked, userAccount, signOutGoogle } = useApp();
  const [activeTab, setActiveTab] = useState('DASHBOARD');
  const [subScreen, setSubScreen] = useState<string | null>(null);
  const [selectedDocId, setSelectedDocId] = useState<string | null>(null);

  // App initialization check
  if (!isDbReady) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color={COLORS.primary} />
        <Text style={styles.loadingText}>Unlocking Secure Registry...</Text>
      </View>
    );
  }

  // Google Authentication Overlay
  if (!userAccount) {
    return (
      <SafeAreaView style={styles.container}>
        <StatusBar barStyle="light-content" backgroundColor={COLORS.background} />
        <LoginScreen />
      </SafeAreaView>
    );
  }

  // Force onboarding if no profile exists
  if (profiles.length === 0) {
    return (
      <SafeAreaView style={styles.container}>
        <StatusBar barStyle="light-content" backgroundColor={COLORS.background} />
        <OnboardingScreen />
      </SafeAreaView>
    );
  }

  // Security screen overlay
  if (pinLocked) {
    return (
      <SafeAreaView style={styles.container}>
        <StatusBar barStyle="light-content" backgroundColor={COLORS.background} />
        <AuthPINScreen />
      </SafeAreaView>
    );
  }

  // Router layout
  const renderScreen = () => {
    // 1. Check Sub-screens first
    if (subScreen === 'PROFILE_MANAGE') {
      return <ProfileManageScreen onBack={() => setSubScreen(null)} />;
    }
    if (subScreen === 'UPLOAD') {
      return <DocumentUploadScreen onBack={() => setSubScreen(null)} />;
    }
    if (subScreen === 'DOC_DETAIL' && selectedDocId) {
      return <DocumentDetailScreen docId={selectedDocId} onBack={() => {
        setSelectedDocId(null);
        setSubScreen(null);
      }} />;
    }
    if (subScreen === 'PIN_SETUP') {
      return <PINSetupScreen onBack={() => setSubScreen(null)} />;
    }

    // 2. Fall back to main tab panels
    switch (activeTab) {
      case 'DASHBOARD':
        return (
          <DashboardScreen
            setTab={setActiveTab}
            onAddProfilePress={() => setSubScreen('PROFILE_MANAGE')}
            onUploadPress={() => setSubScreen('UPLOAD')}
          />
        );
      case 'RECORDS':
        return (
          <DocumentListScreen
            onSelectDoc={(id) => {
              setSelectedDocId(id);
              setSubScreen('DOC_DETAIL');
            }}
          />
        );
      case 'TRENDS':
        return <TrendsScreen />;
      case 'INSIGHTS':
        return <AIInsightsScreen />;
      case 'SETTINGS':
        return <SettingsScreen onPINSetupPress={() => setSubScreen('PIN_SETUP')} />;
      default:
        return <DashboardScreen setTab={setActiveTab} onAddProfilePress={() => setSubScreen('PROFILE_MANAGE')} onUploadPress={() => setSubScreen('UPLOAD')} />;
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor={COLORS.background} />

      {/* App Header Bar */}
      {subScreen === null && (
        <View style={styles.appHeader}>
          <View style={styles.headerTitleRow}>
            <Brain size={22} color={COLORS.primaryLight} />
            <Text style={styles.headerTitle}>HeRe</Text>
          </View>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
              {userAccount?.photoUrl ? (
                <Image
                  source={{ uri: userAccount.photoUrl }}
                  style={{ width: 24, height: 24, borderRadius: 12, marginRight: 6, backgroundColor: COLORS.cardBorder }}
                />
              ) : (
                <View style={{
                  width: 24,
                  height: 24,
                  borderRadius: 12,
                  marginRight: 6,
                  backgroundColor: COLORS.primary + '30',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderColor: COLORS.primaryLight + '50',
                  borderWidth: 1
                }}>
                  <User size={10} color={COLORS.primaryLight} />
                </View>
              )}
              {Platform.OS === 'web' && (
                <View style={{ marginRight: 4 }}>
                  <Text style={{ color: COLORS.textLight, fontSize: 10, fontWeight: 'bold' }}>{userAccount?.name}</Text>
                  <Text style={{ color: COLORS.textMuted, fontSize: 8 }}>{userAccount?.email}</Text>
                </View>
              )}
            </View>

            <TouchableOpacity 
              style={{
                paddingVertical: 4,
                paddingHorizontal: 8,
                borderRadius: BORDER_RADIUS.sm,
                backgroundColor: 'rgba(239, 68, 68, 0.1)',
                borderColor: 'rgba(239, 68, 68, 0.3)',
                borderWidth: 0.5,
                flexDirection: 'row',
                alignItems: 'center',
                gap: 4
              }}
              onPress={async () => {
                Alert.alert(
                  'Sign Out',
                  'Are you sure you want to sign out of your Google account?',
                  [
                    { text: 'Cancel', style: 'cancel' },
                    { 
                      text: 'Sign Out', 
                      style: 'destructive',
                      onPress: async () => {
                        await signOutGoogle();
                      }
                    }
                  ]
                );
              }}
            >
              <LogOut size={10} color={COLORS.danger} />
              <Text style={{ color: COLORS.danger, fontSize: 9, fontWeight: 'bold' }}>Sign Out</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}

      {/* Primary view content */}
      <View style={styles.body}>{renderScreen()}</View>

      {/* Custom Tab Navigator Bar */}
      {subScreen === null && (
        <NavBar currentTab={activeTab} setTab={setActiveTab} />
      )}
    </SafeAreaView>
  );
};

export default function App() {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
}

